CREATE FUNCTION public.record_reading(_lesson uuid,_start int) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pos int; finish int; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF NOT EXISTS(SELECT 1 FROM lessons WHERE id=_lesson AND youtube_id IS NULL) THEN RAISE EXCEPTION 'Reading progress is for transcript-only lessons'; END IF; INSERT INTO user_progress(user_id,lesson_id) VALUES(auth.uid(),_lesson) ON CONFLICT DO NOTHING; SELECT max_watched_sec INTO pos FROM user_progress WHERE user_id=auth.uid() AND lesson_id=_lesson FOR UPDATE; SELECT end_sec INTO finish FROM transcript_chunks WHERE lesson_id=_lesson AND start_sec=_start AND start_sec<=pos AND end_sec>pos ORDER BY end_sec LIMIT 1; IF finish IS NULL THEN RAISE EXCEPTION 'Read the transcript segments in order'; END IF; UPDATE user_progress SET max_watched_sec=finish,updated_at=now() WHERE user_id=auth.uid() AND lesson_id=_lesson; RETURN finish; END $$;
REVOKE ALL ON FUNCTION public.record_reading FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_reading TO authenticated;